module mx4tol_bh( //Verilog 2001,2005 module port syn  
input En;  
input [3:0] D, //输入端口声明  
input [1:0] S, //输入端口声明  
output reg Y //输出端口及变量的数据类型声明  
);  
always @ (D,S,En) //Verilog 2001,2005 syntax  
begin  
if (En == 1) Y = 0; //当En为1时，输出为0  
else //当En为0时，实现选择器的功能  
case (S)  
2'd0: Y = D[0];  
2'd1: Y = D[1];  
2'd2: Y = D[2];  
2'd3: Y = D[3];  
endcase  
end  
endmodule

module mx2tol1 (
    input D1, D0, S,
    output Y
);
    assign Y = S ? D1 : D0; //用连续赋值语句和条件运算符建模
endmodule
//下面给出另一种描述方式
